/**
 * LEAD-DB bulk loader — import a large CSV or JSON file of leads into a named
 * EmailList, server-side, using the SAME idempotent dedup/ingest logic as the
 * admin importer (lib/coldemail/import.ts + lib/coldemail/lead-store.ts). Use this
 * instead of the web importer for big files (tens of thousands of rows) — there's
 * no request timeout here.
 *
 * IDEMPOTENT: re-running the same file inserts 0 (all rows match existing and are
 * updated in place). DEAD/suppressed contacts are never resurrected.
 *
 * Usage:
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Q3 prospects"
 *   npx tsx scripts/import-leads.ts --file leads.json --list-id <listId> --consent
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Cold UK" --create-list
 *
 * Flags:
 *   --file <path>        CSV or JSON file (JSON = array of objects; keys use the
 *                        same header names/aliases as CSV). Required.
 *   --list <name>        Target list by name. Errors if ambiguous/absent unless
 *                        --create-list is given.
 *   --list-id <id>       Target list by id (takes precedence over --list).
 *   --create-list        Create the list (by --list name) if it doesn't exist.
 *   --consent            Record a LEGITIMATE_INTEREST consent row for each NEW contact.
 *   --note <text>        Provenance note stored on the ImportBatch — how/where this
 *                        batch was sourced (e.g. "Manual research via <directory URL>,
 *                        2026-08-25"). ALWAYS pass this for a research-sourced batch;
 *                        it's the only batch-level record of provenance (see the
 *                        `sourceUrl` column for PER-CONTACT provenance, below).
 *   --dry-run            Parse + report row counts only; write nothing.
 *
 * CSV headers spec: see docs/DOCUMENTATION.md (Lead database → Import). Minimum: an
 * `email` column. Everything else (name, fullName, title, website, phone, city, …)
 * is optional and mapped through IMPORT_HEADER_ALIASES. A `source`/`sourceUrl` column
 * (the specific URL this contact's email was found on) is recorded on that contact's
 * ConsentRecord.note when --consent is passed, so provenance is checkable per-contact.
 */
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import {
  ingestLeads,
  parseCsv,
  csvToLeadRows,
  IMPORT_HEADER_ALIASES,
  type LeadRow,
} from "../lib/coldemail/import";
import { prismaLeadStore } from "../lib/coldemail/lead-store";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 ? process.argv[i + 1] : undefined;
}
function flag(name: string): boolean {
  return process.argv.includes(`--${name}`);
}

/** Map an arbitrary JSON object's keys onto canonical LeadRow fields via the aliases. */
function jsonObjToLeadRow(obj: Record<string, unknown>): LeadRow {
  const lead: LeadRow = {};
  for (const [k, v] of Object.entries(obj)) {
    const field = IMPORT_HEADER_ALIASES[k.trim().toLowerCase()];
    if (field && v != null) lead[field] = String(v).trim();
  }
  return lead;
}

async function main(): Promise<void> {
  const filePath = arg("file");
  if (!filePath) {
    console.error("ERROR: --file <path> is required. See the header of this script for usage.");
    process.exit(1);
  }

  const listName = arg("list");
  const listIdArg = arg("list-id");
  const createList = flag("create-list");
  const recordConsent = flag("consent");
  const dryRun = flag("dry-run");
  const note = arg("note") ?? "";

  // ---- Load + parse the file into LeadRow[] ----
  const raw = readFileSync(filePath, "utf8");
  let rows: LeadRow[];
  if (filePath.toLowerCase().endsWith(".json")) {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error("JSON file must be an array of lead objects.");
    rows = parsed.map((o) => jsonObjToLeadRow(o as Record<string, unknown>));
  } else {
    const { headers, rows: csvRows } = parseCsv(raw);
    if (headers.length === 0) throw new Error("Could not parse a header row from the CSV.");
    rows = csvToLeadRows(headers, csvRows);
  }
  console.log(`Parsed ${rows.length} row(s) from ${filePath}.`);

  if (dryRun) {
    console.log("--dry-run: no changes written.");
    await db.$disconnect();
    return;
  }

  // ---- Resolve the target list ----

1	// Cold Email Engine — LEAD-DATABASE bulk import + continuous ingestion core.
2	//
3	// PURE ORCHESTRATION over an injected `LeadStore` so the exact same idempotent
4	// dedup/ingest logic runs from (a) the admin server action, (b) the operator CLI
5	// script scripts/import-leads.ts, and (c) the tests (with an in-memory store, no
6	// DB). The store is the ONLY thing that touches Prisma.
7	//
8	// IDEMPOTENCY + HYGIENE GUARANTEES:
9	//   - Dedup by NORMALIZED email (primary key of a lead). A repeat of an email
10	//     already seen earlier in the same file is skipped (skippedDup).
11	//   - An incoming email that matches an existing contact UPDATES it (fills blanks,
12	//     re-adds to the target list) — never inserts a duplicate. So a re-import of
13	//     the same file inserts 0.
14	//   - An incoming email that matches an existing DEAD or globally-SUPPRESSED
15	//     contact is NOT resurrected (skippedDead) — no update, no re-add to a list.
16	//   - A brand-new email that is already on the global suppression list is refused
17	//     (skippedDead) — we never add a suppressed address.
18	//   - Secondary signal: phone/website(domain) are recorded on the Business but the
19	//     dedup key is always the email (the only reliable per-person identifier).
20	
21	import { normalizeEmail, emailDomain, normalizeDomain } from "@/lib/coldemail/compliance";
22	import { isDeadStatus, type EmailStatusValue } from "@/lib/coldemail/leaddb";
23	
24	// ---------------------------------------------------------------------------
25	// Row model + header spec
26	// ---------------------------------------------------------------------------
27	
28	/**
29	 * Canonical field names an import row can carry. The CSV header row is mapped onto
30	 * these via IMPORT_HEADER_ALIASES; a JSON array uses these keys directly.
31	 */
32	export type LeadRow = {
33	  email?: string;
34	  fullName?: string;
35	  title?: string;
36	  // Business fields:
37	  name?: string; // business name
38	  category?: string;
39	  businessType?: string;
40	  website?: string;
41	  phone?: string;
42	  addressLine?: string;
43	  city?: string;
44	  region?: string;
45	  country?: string;
46	  companySize?: string;
47	  // Provenance: the specific URL/page this contact's email was found on. Not stored on
48	  // the Contact/Business row — threaded through to the per-contact ConsentRecord.note so
49	  // a batch's lawful-basis evidence is checkable one contact at a time (see recordConsent).
50	  sourceUrl?: string;
51	};
52	
53	/**
54	 * Header alias → canonical field. Superset of the legacy Businesses importer so old
55	 * files keep working. Keys are compared lower-cased + trimmed.
56	 */
57	export const IMPORT_HEADER_ALIASES: Record<string, keyof LeadRow> = {
58	  email: "email",
59	  "email address": "email",
60	  "e-mail": "email",
61	  contactemail: "email",
62	  fullname: "fullName",
63	  "full name": "fullName",
64	  contact: "fullName",
65	  contactname: "fullName",
66	  "contact name": "fullName",
67	  name2: "fullName",
68	  person: "fullName",
69	  title: "title",
70	  role: "title",
71	  jobtitle: "title",
72	  "job title": "title",
73	  name: "name",
74	  business: "name",
75	  company: "name",
76	  "company name": "name",
77	  organization: "name",
78	  category: "category",
79	  industry: "category",
80	  type: "businessType",
81	  businesstype: "businessType",
82	  website: "website",
83	  url: "website",
84	  domain: "website",
85	  phone: "phone",
86	  tel: "phone",
87	  telephone: "phone",
88	  address: "addressLine",
89	  addressline: "addressLine",
90	  street: "addressLine",
91	  city: "city",
92	  region: "region",
93	  state: "region",
94	  province: "region",
95	  country: "country",
96	  size: "companySize",
97	  companysize: "companySize",
98	  employees: "companySize",
99	  source: "sourceUrl",
100	  sourceurl: "sourceUrl",
101	  "source url": "sourceUrl",
102	  source_url: "sourceUrl",
103	  foundat: "sourceUrl",
104	  "found at": "sourceUrl",
105	};
106	
107	/** Human-facing spec for the import UI + docs (defined in a client-safe module). */
108	export { IMPORT_HEADERS_SPEC } from "./import-spec";
109	
110	// ---------------------------------------------------------------------------
111	// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
112	// ---------------------------------------------------------------------------
113	
114	export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
115	  const records: string[][] = [];
116	  let field = "";
117	  let row: string[] = [];
118	  let inQuotes = false;
119	  const src = (text ?? "").replace(/\r\n?/g, "\n");
120	
121	  for (let i = 0; i < src.length; i++) {
122	    const c = src[i];
123	    if (inQuotes) {
124	      if (c === '"') {
125	        if (src[i + 1] === '"') {
126	          field += '"';
127	          i++;
128	        } else {
129	          inQuotes = false;
130	        }
131	      } else {
132	        field += c;
133	      }
134	    } else if (c === '"') {
135	      inQuotes = true;
136	    } else if (c === ",") {
137	      row.push(field);
138	      field = "";
139	    } else if (c === "\n") {
140	      row.push(field);
141	      records.push(row);
142	      row = [];
143	      field = "";
144	    } else {
145	      field += c;
146	    }
147	  }
148	  if (field.length > 0 || row.length > 0) {
149	    row.push(field);
150	    records.push(row);
151	  }
152	
153	  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
154	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
155	  const headers = nonEmpty[0].map((h) => h.trim());
156	  return { headers, rows: nonEmpty.slice(1) };
157	}
158	
159	/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
160	export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
161	  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
162	  return rows.map((r) => {
163	    const lead: LeadRow = {};
164	    cols.forEach((field, i) => {
165	      if (field) lead[field] = (r[i] ?? "").trim();
166	    });
167	    return lead;
168	  });
169	}
170	
171	// ---------------------------------------------------------------------------
172	// Normalisation + validation of a single lead row
173	// ---------------------------------------------------------------------------
174	
175	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
176	
177	export type NormalizedLead = {
178	  email: string;
179	  domain: string;
180	  fullName: string;
181	  title: string;
182	  business: {
183	    name: string;
184	    category: string;
185	    businessType: string;
186	    website: string;
187	    phone: string;
188	    addressLine: string;
189	    city: string;
190	    region: string;
191	    country: string;
192	    companySize: string;
193	  };
194	  sourceUrl: string;
195	};
196	
197	/**
198	 * Normalise + validate a row. Returns null when there is no usable email — the lead
199	 * database is keyed on emailable people, so an email-less row can't be a lead. The
200	 * business name falls back to the email domain so a name-less row still imports.
201	 */
202	export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
203	  const email = normalizeEmail(raw.email);
204	  if (!email || !EMAIL_RE.test(email)) return null;
205	  const domain = emailDomain(email);
206	  const website = (raw.website ?? "").trim();
207	  const name = (raw.name ?? "").trim() || domain;
208	  return {
209	    email,
210	    domain,
211	    fullName: (raw.fullName ?? "").trim().slice(0, 160),
212	    title: (raw.title ?? "").trim().slice(0, 120),
213	    business: {
214	      name: name.slice(0, 160),
215	      category: (raw.category ?? "").trim().slice(0, 120),
216	      businessType: (raw.businessType ?? "").trim().slice(0, 120),
217	      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
218	      phone: (raw.phone ?? "").trim().slice(0, 60),
219	      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
220	      city: (raw.city ?? "").trim().slice(0, 120),
221	      region: (raw.region ?? "").trim().slice(0, 120),
222	      country: (raw.country ?? "").trim().slice(0, 120),
223	      companySize: (raw.companySize ?? "").trim().slice(0, 60),
224	    },
225	    sourceUrl: (raw.sourceUrl ?? "").trim().slice(0, 300),
226	  };
227	}
228	
229	// ---------------------------------------------------------------------------
230	// The store the ingest orchestrator drives (Prisma in prod, a fake in tests)
231	// ---------------------------------------------------------------------------
232	
233	export type ExistingContact = {
234	  id: string;
235	  businessId: string;
236	  emailStatus: EmailStatusValue | string;
237	  fullName: string;
238	  title: string;
239	};
240	
241	export interface LeadStore {
242	  /** Find a contact by NORMALIZED email, or null. */
243	  findContact(email: string): Promise<ExistingContact | null>;
244	  /** Is this email (or its domain) on the global suppression list? */
245	  isSuppressed(email: string): Promise<boolean>;
246	  /** Create a Business, return its id. */
247	  createBusiness(data: NormalizedLead["business"], batchId: string | null): Promise<string>;
248	  /** Create a Contact (status UNVERIFIED), return its id. */
249	  createContact(
250	    input: { businessId: string; email: string; fullName: string; title: string },
251	    batchId: string | null,
252	  ): Promise<string>;
253	  /** Fill blank fields on an existing contact (never overwrite non-empty). */
254	  updateContact(
255	    id: string,
256	    input: { fullName?: string; title?: string },
257	    batchId: string | null,
258	  ): Promise<void>;
259	  /** Add a contact to a list, idempotently (no-op if already a member). */
260	  addToList(contactId: string, listId: string): Promise<void>;
261	  /**
262	   * Record a lawful-basis consent row for a newly-created contact. `note`, when given,
263	   * is the per-contact provenance (the specific URL the email was found on) — kept
264	   * separate from `source` (a batch-wide label like "script import") so the evidence is
265	   * checkable contact-by-contact.
266	   */
267	  recordConsent(contactId: string, source: string, note?: string): Promise<void>;
268	}
269	
270	// ---------------------------------------------------------------------------
271	// The ingest orchestrator
272	// ---------------------------------------------------------------------------
273	
274	export type ImportResult = {
275	  totalRows: number;
276	  inserted: number;
277	  updated: number;
278	  skippedDead: number;
279	  skippedDup: number;
280	  skippedInvalid: number;
281	  contactIds: string[];
282	};
283	
284	export type IngestOptions = {
285	  store: LeadStore;
286	  listId: string | null;
287	  batchId?: string | null;
288	  recordConsent?: boolean;
289	  consentSource?: string;
290	};
291	
292	/**
293	 * Ingest normalized-or-raw rows into the lead database, idempotently.
294	 *
295	 * For each row (see file header for the full guarantee set): validate → dedup
296	 * within the file → look up the existing contact → refuse dead/suppressed →
297	 * update-or-insert → add to the target list. Returns the batch tally.
298	 */
299	export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
300	  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
301	  const result: ImportResult = {
302	    totalRows: rows.length,
303	    inserted: 0,
304	    updated: 0,
305	    skippedDead: 0,
306	    skippedDup: 0,
307	    skippedInvalid: 0,
308	    contactIds: [],
309	  };
310	
311	  const seen = new Set<string>(); // in-file dedup by normalized email
312	
313	  for (const raw of rows) {
314	    const lead = normalizeLeadRow(raw);
315	    if (!lead) {
316	      result.skippedInvalid++;
317	      continue;
318	    }
319	    if (seen.has(lead.email)) {
320	      result.skippedDup++;
321	      continue;
322	    }
323	    seen.add(lead.email);
324	
325	    const existing = await store.findContact(lead.email);
326	
327	    if (existing) {
328	      // NEVER resurrect a dead/suppressed contact.
329	      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
330	        result.skippedDead++;
331	        continue;
332	      }
333	      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
334	      await store.updateContact(
335	        existing.id,
336	        {
337	          fullName: existing.fullName ? undefined : lead.fullName || undefined,
338	          title: existing.title ? undefined : lead.title || undefined,
339	        },
340	        batchId,
341	      );
342	      if (listId) await store.addToList(existing.id, listId);
343	      result.updated++;
344	      result.contactIds.push(existing.id);
345	      continue;
346	    }
347	
348	    // Brand-new email: refuse if it's already globally suppressed (opted-out before
349	    // the contact row existed) — we never add a suppressed address.
350	    if (await store.isSuppressed(lead.email)) {
351	      result.skippedDead++;
352	      continue;
353	    }
354	
355	    const businessId = await store.createBusiness(lead.business, batchId);
356	    const contactId = await store.createContact(
357	      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
358	      batchId,
359	    );
360	    if (listId) await store.addToList(contactId, listId);
361	    if (recordConsent) await store.recordConsent(contactId, consentSource, lead.sourceUrl || undefined);
362	    result.inserted++;
363	    result.contactIds.push(contactId);
364	  }
365	
366	  return result;
367	}
